import Foundation

/// Scaffolds a starter `Hybrid<Name>.swift` file for the `init` subcommand.
/// Pure string + name handling — the CLI owns disk I/O.
///
/// The template lifts the chicken-and-egg boilerplate (`#if canImport(NitroModules)`,
/// `: Hybrid<Name>Spec`, `super.init()`) out of what a brand-new user has to type
/// from scratch. A first reader of the generated file should see the leading
/// docstring before the conformance, so the references aren't surprising.
public enum InitTemplate {
    /// Accepts either the bare spec name (`Counter`) or the class name with
    /// a `Hybrid` prefix (`HybridCounter`). Returns the bare spec name.
    ///
    /// `Hybrid` alone is rejected: it's the prefix, not a spec name, and the
    /// extractor's matching convention requires at least one character after it.
    public static func normalize(rawName: String) throws -> String {
        let trimmed = rawName.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed == "Hybrid" {
            throw InitTemplateError.invalidName(rawName)
        }
        let stripped: String
        if trimmed.hasPrefix("Hybrid"), trimmed.count > "Hybrid".count {
            stripped = String(trimmed.dropFirst("Hybrid".count))
        } else {
            stripped = trimmed
        }
        guard isValidSwiftIdentifier(stripped) else {
            throw InitTemplateError.invalidName(rawName)
        }
        return stripped
    }

    public static func render(specName: String) -> String {
        let className = "Hybrid\(specName)"
        let lines: [String] = [
            "// \(className).swift — generated by `nitrogen-swift-input init \(specName)`.",
            "//",
            "// This file is BOTH:",
            "//   1. The spec source — parsed by `nitrogen-swift-input` (SwiftSyntax, no",
            "//      typecheck) to emit `\(specName).nitro.ts` + `\(specName).ir.json`.",
            "//   2. The implementation — compiled into the Pod that ships in the RN app.",
            "//",
            "// The `: \(className)Spec` inheritance and `import NitroModules` only resolve",
            "// after `bun nitrogen` produces",
            "// `nitrogen/generated/ios/swift/\(className)Spec.swift` and `pod install`",
            "// brings in NitroModules. The `#if canImport(NitroModules)` wrap lets this",
            "// file parse cleanly before that first codegen run.",
            "//",
            "// Standard Swift from here on — add public methods, run codegen, ship.",
            "",
            "#if canImport(NitroModules)",
            "import NitroModules",
            "",
            "public final class \(className): \(className)Spec {",
            "    public override init() { super.init() }",
            "",
            "    // Add public methods here. Supported parameter / return types: Bool,",
            "    // Double, Float, Int64, UInt64, Void. Example:",
            "    //",
            "    //   public func add(a: Double, b: Double) throws -> Double { a + b }",
            "}",
            "#endif",
        ]
        return lines.joined(separator: "\n") + "\n"
    }

    private static func isValidSwiftIdentifier(_ s: String) -> Bool {
        guard let first = s.first else { return false }
        guard first.isLetter || first == "_" else { return false }
        for ch in s.dropFirst() {
            guard ch.isLetter || ch.isNumber || ch == "_" else { return false }
        }
        return true
    }
}

public enum InitTemplateError: Error, CustomStringConvertible, Equatable {
    case invalidName(String)

    public var description: String {
        switch self {
        case .invalidName(let name):
            return "'\(name)' is not a valid spec name (expected a Swift identifier like `Counter`)"
        }
    }
}
